// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, bytes calldata _data) public {
        vm.assume(callee != address(0) && callee != address(c));
        // Deploy a simple contract that always reverts on any call
        Reverter reverter = new Reverter();
        // Call forward with a target that will revert
        (bool success,) = address(c).call(abi.encodeWithSignature("forward(address,bytes)", address(reverter), _data));
        assertTrue(!success, "forward should revert when inner call fails");
    }
}

contract Reverter {
    fallback() external payable {
        revert("always revert");
    }
}
